	}

	private Transferable copyDataText(bool followPointers) {
		AddressSetView addrs = getSelectedAddresses();
		List<string> strings = new();
		Listing listing = currentProgram.getListing();
		if (addrs is ProgramSelection programSelection &&
			programSelection.getInteriorSelection() != null) {
			InteriorSelection interiorSelection = programSelection.getInteriorSelection();
			copyInteriorDataText(strings, listing, interiorSelection, followPointers);
		}
		else {
			foreach (Data data in listing.getData(addrs, true)) {
				string string = getString(data, followPointers);
				if (string != null) {
					strings.add(string);
				}
			}
		}
		return createStringTransferable(string.join("\n", strings));
	}

	private void copyInteriorDataText(List<string> strings, Listing listing,
			InteriorSelection interior, bool followPointers) {

		Data outer = listing.getDataContaining(interior.getStartAddress());
		ProgramLocation from = interior.getFrom();
		ProgramLocation to = interior.getTo();
		Data first = outer.getComponent(from.getComponentPath());
		Data last = outer.getComponent(to.getComponentPath());
		if (first == null || last == null) {
			return;
		}

		// We have a selection inside a data that has child elements. This may be several levels
		// deep. The first and last data retrieved above are children in the same parent. So
		// get the index of the first and last data in that parent and add string data for each
		// selected element in that parent.
		Data parent = first.getParent();
		int startIndex = first.getComponentIndex();
		int endIndex = last.getComponentIndex();
		for (int i = startIndex; i <= endIndex; i++) {
			Data child = parent.getComponent(i);
			string string = getString(child, followPointers);
			if (string != null) {
				strings.add(string);
			}
		}
	}

	private Data getReferencedData(Data data, Set<Address> visited) {
		object value = data.getValue();
		if (!(value is Address address)) {
			return null;
		}
		if (visited.contains(address)) {
			return null;
		}
		visited.add(address);
		Data referenced = currentProgram.getListing().getDataAt(address);
		if (referenced == null) {
			return null;
		}
		if (referenced.isPointer()) {
			return getReferencedData(referenced, visited);
		}
		return referenced;
	}

	private string getString(Data data, bool followPointers) {
		if (!followPointers) {
			return getString(data);
		}
		// if following pointers and data is not a pointer, then nothing to do
		if (!data.isPointer()) {
			return null;
		}

		// otherwise follow pointers to non-pointer data and return its string
		Set<Address> visited = new();
		Data referenced = getReferencedData(data, visited);
		return getString(referenced);
	}

	private string getString(Data data) {
		// For now, don't get string data for compound object such as structures, unions, or arrays
		if (data == null || data.getNumComponents() > 0) {
			return null;
		}
		object value = data.getValue();
		if (value is string s) {
			if (includeQuotesForStringData) {
				return "\"" + s + "\"";
			}
			return s;
		}
		return data.getDefaultValueRepresentation();
	}

	private bool pasteLabelsComments(Transferable pasteData, bool pasteLabels,
			bool pasteComments) {
		try {
			List<object> list =
				(List<object>) pasteData.getTransferData(CodeUnitInfoTransferable.localDataTypeFlavor);
			List<CodeUnitInfo> infos = CollectionUtils.asList(list, typeof(CodeUnitInfo));
			CodeUnitInfoPasteCmd cmd = new CodeUnitInfoPasteCmd(currentLocation.getAddress(), infos,
				pasteLabels, pasteComments);
			return tool.execute(cmd, currentProgram);
		}
		catch (Exception e) {
			string msg = e.getMessage();
			if (msg == null) {
				msg = e.toString();
			}
			tool.setStatusInfo("Paste failed: " + msg, true);
		}

		return false;
	}

	private bool pasteLabelString(Transferable pasteData)
    {

		string labelName =
			(string) pasteData.getTransferData(LabelStringTransferable.labelStringFlavor);
		Address address = currentLocation.getAddress();
		if (currentLocation is LabelFieldLocation) {
			LabelFieldLocation labelFieldLocation = (LabelFieldLocation) currentLocation;
			string oldName = labelFieldLocation.getName();
			RenameLabelCmd cmd =
				new RenameLabelCmd(address, oldName, labelName, SourceType.USER_DEFINED);
			return tool.execute(cmd, currentProgram);
		}
		else if (currentLocation is FunctionNameFieldLocation) {
			FunctionNameFieldLocation functionNameLocation =
				(FunctionNameFieldLocation) currentLocation;
			string oldName = functionNameLocation.getFunctionName();
			RenameLabelCmd cmd =
				new RenameLabelCmd(address, oldName, labelName, SourceType.USER_DEFINED);
			return tool.execute(cmd, currentProgram);
		}
		else if (currentLocation is OperandFieldLocation) {
			return pasteOperandField((OperandFieldLocation) currentLocation, labelName);
		}

		// try pasting onto something that is not a label
		return maybePasteNonLabelString(labelName);
	}

	private bool pasteOperandField(OperandFieldLocation operandLocation, string labelName) {

		int opIndex = operandLocation.getOperandIndex();
		Listing listing = currentProgram.getListing();
		Instruction instruction = listing.getInstructionAt(operandLocation.getAddress());
		if (instruction == null) {
			return false;
		}

		Reference reference = instruction.getPrimaryReference(opIndex);
		if (reference == null) {
			return false;
		}

		Variable var = currentProgram.getReferenceManager().getReferencedVariable(reference);
		if (var != null) {
			SetVariableNameCmd cmd =
				new SetVariableNameCmd(var, labelName, SourceType.USER_DEFINED);
			return tool.execute(cmd, currentProgram);
		}

		SymbolTable symbolTable = currentProgram.getSymbolTable();
		Symbol symbol = symbolTable.getSymbol(reference);
		if (symbol == null) {
			return false;
		}
		SymbolType type = symbol.getSymbolType();
		if ((type == SymbolType.LABEL) || (type == SymbolType.FUNCTION)) {
			RenameLabelCmd cmd = new RenameLabelCmd(symbol, labelName, SourceType.USER_DEFINED);
			return tool.execute(cmd, currentProgram);
		}

		// try pasting onto something that is not a label
		return maybePasteNonLabelString(labelName);
	}

	private bool pasteNonLabelString(Transferable pasteData)
    {

		string text =
			(string) pasteData.getTransferData(NonLabelStringTransferable.nonLabelStringFlavor);
		return maybePasteNonLabelString(text);
	}

	private bool maybePasteNonLabelString(string string) {
		if (currentLocation is CommentFieldLocation) {
			CommentFieldLocation commentFieldLocation = (CommentFieldLocation) currentLocation;
			Address address = commentFieldLocation.getAddress();
			CommentType commentType = commentFieldLocation.getCommentType();
			if (commentType != null) {
				SetCommentCmd cmd = new SetCommentCmd(address, commentType, string);
				return tool.execute(cmd, currentProgram);
			}
		}
		return false;
	}

	private void getCodeUnitInfo(AddressSetView set, Address startAddr, List<CodeUnitInfo> list,
			bool copyLabels, bool copyComments, TaskMonitor monitor) {
		Map<Address, CodeUnitInfo> map = new();
		if (copyLabels) {
			getFunctions(startAddr, set, list, map, monitor);
			getLabels(startAddr, set, list, map, monitor);
		}
		if (copyComments) {
			getComments(startAddr, set, list, map, monitor);
		}
	}

	private void getFunctions(Address startAddr, AddressSetView set, List<CodeUnitInfo> list,
			Map<Address, CodeUnitInfo> map, TaskMonitor monitor) {

		FunctionIterator it = currentProgram.getListing().getFunctions(set, true);
		while (it.hasNext() && !monitor.isCancelled()) {
			Function function = it.next();
			Address entry = function.getEntryPoint();
			CodeUnitInfo info = getInfoFromMap(list, map, entry, startAddr);
			info.setFunction(function);
		}
	}

	private void getComments(Address startAddr, AddressSetView set, List<CodeUnitInfo> list,
			Map<Address, CodeUnitInfo> map, TaskMonitor monitor) {

		Listing listing = currentProgram.getListing();
		CodeUnitIterator it = listing.getCodeUnitIterator(CodeUnit.COMMENT_PROPERTY, set, true);
		while (it.hasNext() && !monitor.isCancelled()) {
			CodeUnit cu = it.next();
			Address minAddress = cu.getMinAddress();
			CodeUnitInfo info = getInfoFromMap(list, map, minAddress, startAddr);
			setCommentInfo(cu, info);
		}
	}

	private void setCommentInfo(CodeUnit cu, CodeUnitInfo info) {
		foreach (CommentType type in CommentType.values()) {
			string[] comments = cu.getCommentAsArray(type);
			if (comments != null && comments.length > 0) {
				info.setComment(type, comments);
			}
		}
	}

	private void getLabels(Address startAddr, AddressSetView set, List<CodeUnitInfo> list,
			Map<Address, CodeUnitInfo> map, TaskMonitor monitor) {

		SymbolIterator it = currentProgram.getSymbolTable().getPrimarySymbolIterator(set, true);
		while (it.hasNext() && !monitor.isCancelled()) {
			Symbol symbol = it.next();
			Address minAddress = symbol.getAddress();
			Symbol[] symbols = currentProgram.getSymbolTable().getSymbols(minAddress);
			CodeUnitInfo info = getInfoFromMap(list, map, minAddress, startAddr);
			info.setSymbols(symbols);
		}
	}

	private CodeUnitInfo getInfoFromMap(List<CodeUnitInfo> list, Map<Address, CodeUnitInfo> map,
			Address minAddress, Address startAddr) {
		CodeUnitInfo info = map.get(minAddress);
		if (info == null) {
			long index = minAddress.subtract(startAddr);

			info = new CodeUnitInfo((int) index);
			map.put(minAddress, info);
			list.add(info);
		}

		return info;
	}

	/* @Override */
	public bool isValidContext(ActionContext context) {
		if (!(context is CodeViewerActionContext)) {
			return false;
		}
		return context.getComponentProvider() == componentProvider;
	}

	/* @Override */
	public ComponentProvider getComponentProvider() {
		return componentProvider;
	}

	/* @Override */
	public bool enableCopy() {
		return true;
	}

	/* @Override */
	public bool enableCopySpecial() {
		return true;
	}

	/* @Override */
	public bool canCopy() {
		return copyFromSelectionEnabled || stringContent != null ||
			canCopyCurrentLocationWithNoSelection();
	}

	/* @Override */
	public bool canCopySpecial() {
		return currentLocation != null;
	}

	private bool canCopyCurrentLocationWithNoSelection() {

		if (currentLocation is AddressFieldLocation) {
			return true;
		}
		else if (currentLocation is LabelFieldLocation) {
			return true;
		}
		else if (currentLocation is FunctionNameFieldLocation) {
			return true;
		}
		else if (currentLocation is CommentFieldLocation) {
			return true;
		}
		else if (currentLocation is BytesFieldLocation) {
			return true;
		}
		else if (currentLocation is OperandFieldLocation) {
			return true;
		}
		else if (currentLocation is MnemonicFieldLocation) {
			return true;
		}
		else if (currentLocation is VariableLocation) {
			return true;
		}

		return false;
	}

	/* @Override */
	public bool enablePaste() {
		return true;
	}

	/* @Override */
	public bool canPaste(DataFlavor[] availableFlavors) {
		if (availableFlavors != null) {
			foreach (DataFlavor flavor in availableFlavors) {
				if (flavor.equals(LABELS_COMMENTS_TYPE.getFlavor()) ||
					flavor.equals(LABELS_TYPE.getFlavor()) ||
					flavor.equals(COMMENTS_TYPE.getFlavor()) ||
					flavor.equals(BYTE_STRING_TYPE.getFlavor()) ||
					flavor.equals(LabelStringTransferable.labelStringFlavor) ||
					flavor.equals(NonLabelStringTransferable.nonLabelStringFlavor)) {
					return true;
				}
				if (flavor.equals(DataFlavor.stringFlavor)) {
					return true; // check if it is a valid hex string?
				}
			}
		}
		return false;
	}

	/* @Override */
	public void optionsChanged(ToolOptions options, string optionName, object oldValue,
			object newValue)
    {
		if (optionName.equals(ClipboardPlugin.REMOVE_QUOTES_OPTION)) {
			includeQuotesForStringData =
				!options.getBoolean(ClipboardPlugin.REMOVE_QUOTES_OPTION, false);
		}
	}

