	/* @Override */
	public void lostOwnership(Transferable transferable) {
		// unsupported
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private static class LabelStringTransferable : StringTransferable {

		public static readonly DataFlavor labelStringFlavor = new GenericDataFlavor(
			DataFlavor.javaJVMLocalObjectMimeType + "; class=java.lang.String",
			"Local label as string object");

		private DataFlavor[] flavors = { labelStringFlavor, DataFlavor.stringFlavor };
		private List<DataFlavor> flavorList = Arrays.asList(flavors);

		LabelStringTransferable(string name) : base(name)
    {
		}

		/* @Override */
		public object getTransferData(DataFlavor flavor)
    {
			if (flavor.equals(labelStringFlavor)) {
				return data;
			}
			if (flavor.equals(DataFlavor.stringFlavor)) {
				return data;
			}
			throw new UnsupportedFlavorException(flavor);
		}

		/* @Override */
		public DataFlavor[] getTransferDataFlavors() {
			return flavors;
		}

		/* @Override */
		public bool isDataFlavorSupported(DataFlavor flavor) {
			return flavorList.contains(flavor);
		}
	}

	private static class NonLabelStringTransferable : StringTransferable {

		public static readonly DataFlavor nonLabelStringFlavor = new GenericDataFlavor(
			DataFlavor.javaJVMLocalObjectMimeType + "; class=java.lang.String",
			"Local non-label as string object");

		private DataFlavor[] flavors = { nonLabelStringFlavor, DataFlavor.stringFlavor };
		private List<DataFlavor> flavorList = Arrays.asList(flavors);

		NonLabelStringTransferable(string[] text) : base(combine(text))
    {
		}

		private static string combine(string[] text) {
			StringBuilder buildy = new StringBuilder();
			foreach (string string in text) {
				if (buildy.length() > 0) {
					buildy.append('\n');
				}
				buildy.append(string);
			}
			return buildy.toString();
		}

		NonLabelStringTransferable(string text) : base(text)
    {
		}

		/* @Override */
		public object getTransferData(DataFlavor flavor)
    {
			if (flavor.equals(nonLabelStringFlavor)) {
				return data;
			}
			if (flavor.equals(DataFlavor.stringFlavor)) {
				return data;
			}
			throw new UnsupportedFlavorException(flavor);
		}

		/* @Override */
		public DataFlavor[] getTransferDataFlavors() {
			return flavors;
		}

		/* @Override */
		public bool isDataFlavorSupported(DataFlavor flavor) {
			return flavorList.contains(flavor);
		}
	}
}
